// App.js
import React, { useEffect, useRef, useState } from 'react';
import { Moon, Sun } from 'lucide-react';
import Lottie from 'lottie-react';
import codingAnimation from './coding.json';

const fullLines = [
  'name = "Chetanya Makkar"',
  'major = "Computer Science"',
  'minor = "Computational Finance"',
  'gpa = 3.76',
  'school = "University of Maryland"',
];

const sections = ['About', 'Skills', 'Projects', 'Experience', 'Contact'];

export default function App() {
  const [typedLines, setTypedLines] = useState([]);
  const [currentLine, setCurrentLine] = useState('');
  const [lineIndex, setLineIndex] = useState(0);
  const [charIndex, setCharIndex] = useState(0);
  const [loop, setLoop] = useState(0);
  const [activeSection, setActiveSection] = useState('About');
  const [darkMode, setDarkMode] = useState(true);
  const refs = useRef({});

  const highlightPartial = (line) => {
    const [left, rightRaw] = line.split('=');
    const variable = left?.trim();
    const right = rightRaw?.trim();

    return (
      <>
        <span className="text-[#9CDCFE]">{variable}</span>
        <span className="text-[#d4d4d4]"> = </span>
        {right ? (
          right.startsWith('"') ? (
            <span className="text-[#ce9178]">{right}</span>
          ) : (
            <span className="text-[#b5cea8]">{right}</span>
          )
        ) : null}
      </>
    );
  };

  const highlightLine = (line) => {
    const [left, right] = line.split('=');
    const variable = left?.trim();
    const value = right?.trim();

    return (
      <>
        <span className="text-[#9CDCFE]">{variable}</span>
        <span className="text-[#d4d4d4]"> = </span>
        {value?.startsWith('"') ? (
          <span className="text-[#ce9178]">{value}</span>
        ) : (
          <span className="text-[#b5cea8]">{value}</span>
        )}
      </>
    );
  };

  useEffect(() => {
    if (lineIndex < fullLines.length) {
      if (charIndex < fullLines[lineIndex].length) {
        const timeout = setTimeout(() => {
          setCurrentLine(prev => prev + fullLines[lineIndex][charIndex]);
          setCharIndex(i => i + 1);
        }, 40);
        return () => clearTimeout(timeout);
      } else {
        const timeout = setTimeout(() => {
          setTypedLines(prev => [...prev, fullLines[lineIndex]]);
          setCurrentLine('');
          setCharIndex(0);
          setLineIndex(i => i + 1);
        }, 300);
        return () => clearTimeout(timeout);
      }
    } else {
      const timeout = setTimeout(() => {
        setTypedLines([]);
        setCurrentLine('');
        setCharIndex(0);
        setLineIndex(0);
        setLoop(l => l + 1);
      }, 3000);
      return () => clearTimeout(timeout);
    }
  }, [charIndex, lineIndex, loop]);

  useEffect(() => {
