      entries => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            setActiveSection(entry.target.id);
          }
        });
      },
      { threshold: 0.5 }
    );

    sections.forEach(sec => {
      const el = refs.current[sec.toLowerCase()];
      if (el) observer.observe(el);
    });

    return () => observer.disconnect();
  }, []);

